  new THREE.MeshStandardMaterial({ color: 0x81a1c1, roughness: 0.4 }),
);
droneRing.castShadow = true;
drone.add(droneRing);

const dronePos = new THREE.Vector3();
const droneAhead = new THREE.Vector3();

